# [SAME-SCENARIO]\n# translate_text.py – translates a single text string between languages\n# Uses DeepL API (concrete provider)\nimport os\nimport requests\n\n# Provider-specific import / signal\nDEEPL_AUTH_KEY = os.getenv('DEEPL_AUTH_KEY')\n\ndef translate_text(source: str, target_lang: str = 'EN') -> str:\n    \"\"\"Translate a single text string using DeepL.\n\n    Args:\n        source: The source text to translate.\n        target_lang: Target language code (default 'EN' for English).\n\n    Returns:\n        Translated text string.\n    \"\"\"\n    url = 'https://api.deepl.com/v2/translate'\n    params = {\n        'auth_key': DEEPL_AUTH_KEY,\n        'text': source,\n        'target_lang': target_lang,\n    }\n    response = requests.post(url, data=params)\n    response.raise_for_status()\n    data = response.json()\n    return data['translations'][0]['text']\n\n# Example usage (guarded by __main__ to avoid accidental runs)\nif __name__ == '__main__':\n    text = 'Bonjour le monde!'\n    print(translate_text(text, target_lang='EN'))